mapper.select:
SELECT s.id as id, s.service_name as serviceName, sc.type_name as categoryName, s.short_description as shortDescription, tt.type_name as truckTypeName, tt.base_fare as basePrice, s.average_rating as averageRating, s.rating_count as ratingCount FROM service s JOIN service_category sc ON s.category_id = sc.id JOIN truck_type tt ON s.truck_type_id = tt.id
and s.category_id = #{categoryId}
AND s.status = #{status}
ORDER BY s.average_rating DESC, s.rating_count DESC

SELECT
s.id, s.category_id, s.truck_type_id, s.service_name, s.short_description, s.loading_capacity_description,
s.average_rating, s.rating_count, s.status, s.create_time, s.update_time, s.create_user, s.update_user,
sc.type_name AS categoryName,
tt.type_name AS truckTypeName,
ca.name AS createUserName,
ua.name AS updateUserName
FROM service s LEFT JOIN service_category sc ON s.category_id = sc.id
LEFT JOIN truck_type tt ON s.truck_type_id = tt.id
LEFT JOIN admin ca ON s.create_user = ca.id
LEFT JOIN admin ua ON s.update_user = ua.id


        AND s.service_name LIKE CONCAT('%', #{serviceName}, '%')


        AND s.category_id = #{categoryId}


        AND s.truck_type_id = #{truckTypeId}


        AND s.average_rating >= #{minAverageRating}


        AND s.average_rating <= #{maxAverageRating}


        AND s.rating_count >= #{minRatingCount}


        AND s.rating_count <= #{maxRatingCount}


        AND s.status = #{status}


        AND s.create_time >= #{createTimeStart}


        AND s.create_time <= #{createTimeEnd}


ORDER BY s.create_time DESC
